function getChampionInternalKey(name){

  if(!name) return "Aatrox";

  const lower = String(name).trim().toLowerCase();

  if(CHAMPION_INTERNAL_KEYS[lower]) return CHAMPION_INTERNAL_KEYS[lower];

  return String(name).replace(/[^a-zA-Z0-9]/g, "");

}

function getChampionNumericId(name, fallbackId){

  if(fallbackId && Number(fallbackId) > 0) return Number(fallbackId);

  if(!name) return 0;

  const lower = String(name).trim().toLowerCase();

  if(CHAMPION_NUMERIC_IDS[lower]) return CHAMPION_NUMERIC_IDS[lower];

  if(typeof LOL_DATA !== 'undefined' && LOL_DATA.champions){

    const found = LOL_DATA.champions.find(c => (c.name && c.name.toLowerCase() === lower) || (c.id && c.id.toLowerCase() === lower));

    if(found && found.key) return Number(found.key);

  }

  return 0;

}

function getChampionIconUrl(name, id){

  const numId = getChampionNumericId(name, id);

  if(numId > 0){

    return `https://raw.communitydragon.org/latest/plugins/rcp-be-lol-game-data/global/default/v1/champion-icons/${numId}.png`;

  }

  const key = getChampionInternalKey(name);

  return `https://ddragon.leagueoflegends.com/cdn/16.18.1/img/champion/${key}.png`;

}

const ROLE_ICONS = {

  "top": "data:image/png;base64,",

  "jungle": "data:image/png;base64,",

  "middle": "data:image/png;base64,",

  "bottom": "data:image/png;base64,",

  "utility": "data:image/png;base64,",

  "aram": "data:image/png;base64,",

  "fill": "data:image/png;base64,"

};

function getRoleIcon(role){

  if(!role)return ROLE_ICONS.fill;

  const l=role.toLowerCase();

  if(l.includes("aram"))return ROLE_ICONS.aram;

  if(l.includes("top"))return ROLE_ICONS.top;

  if(l.includes("jungle")||l.includes("jg"))return ROLE_ICONS.jungle;

  if(l.includes("mid")||l.includes("middle"))return ROLE_ICONS.middle;

  if(l.includes("adc")||l.includes("bot")||l.includes("bottom"))return ROLE_ICONS.bottom;

  if(l.includes("sup")||l.includes("utility"))return ROLE_ICONS.utility;

  return ROLE_ICONS.fill;

}

function escapeHtml(s){

  return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");

}

function formatPlayerHtml(name){

  if(!name)return "";

  const strip = document.getElementById("stripTagsCheck") && document.getElementById("stripTagsCheck").checked;

  let display = name;

  if(strip){

    display = display.replace(/\s*#\S+$/,"").trim() || display;

  }

  const m=display.match(/^(.*?)(#.*)$/);

  if(m){

    return `<span class="player-name" title="${escapeHtml(display)}">${escapeHtml(m[1].trim())}</span><span class="player-tag">${escapeHtml(m[2])}</span>`;

  }

  return `<span class="player-name" title="${escapeHtml(display)}">${escapeHtml(display)}</span>`;

}


function getTargetLaneFromRole(role){

  if(!role) return null;

  const l = role.trim().toLowerCase();

  if(l.includes("top")) return "Top";

  if(l.includes("jungle") || l.includes("jg")) return "Jungle";

  if(l.includes("mid") || l.includes("middle")) return "Mid";

  if(l.includes("adc") || l.includes("bot") || l.includes("bottom")) return "ADC";

  if(l.includes("sup") || l.includes("utility")) return "Support";

  return null;

}

function getCandidateChampionsForRole(role, usedChampIds = new Set()){

  if(!LOL_DATA.champions || LOL_DATA.champions.length === 0) return [];

  const targetLane = getTargetLaneFromRole(role);

  if(targetLane){

    const candidates = LOL_DATA.champions.filter(c => !usedChampIds.has(c.id) && Array.isArray(c.lanes) && c.lanes.includes(targetLane));

    if(candidates.length > 0) return candidates;

  }

  const unused = LOL_DATA.champions.filter(c => !usedChampIds.has(c.id));

  if(unused.length > 0) return unused;

  return LOL_DATA.champions;

}


